The fixture's forbidden pattern is deliberately 'console.log'. Never use one of this board's own globalRails.forbiddenPatterns strings in the fixture, or this plan's text trips them.
```ts
// GLOBAL MODIFY_RAIL / REMOVE_RAIL reach the two lists submit_plan enforces
// (forbiddenPatterns, requiredPatterns) as well as customRules (task-34e42a0a).
import fs from 'fs';
import path from 'path';
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { ToolTestHarness } from './toolTestHarness.js';
import { proposeRailTool } from './proposeRail.js';
import { submitPlanTool } from './submitPlan.js';
import { MoeError } from '../util/errors.js';

const RAILS = {
  techStack: [], formatting: '', testing: '',
  forbiddenPatterns: ['rm -rf', 'console.log'],
  requiredPatterns: ['error handling', 'test'],
  customRules: ['Keep it simple'],
};

describe('moe.propose_rail GLOBAL rail lists (task-34e42a0a)', () => {
  const h = new ToolTestHarness();
  beforeEach(async () => {
    h.init();
    h.setupMoeFolder({ globalRails: structuredClone(RAILS) });
    h.createEpic();
    h.createTask({ status: 'PLANNING', assignedWorkerId: 'architect-1' });
    await h.state.load();
  });
  afterEach(() => { vi.restoreAllMocks(); h.cleanup(); });

  const plan = (description: string) => ({ taskId: 'task-1', workerId: 'architect-1', steps: [{ description, affectedFiles: ['file.ts'] }] });
  const FORBIDDEN_PLAN = plan('Replace the console.log call with the logger, with error handling and a test');
  const REQUIRED_PLAN = plan('Rename a constant and add a test');
  const submit = (p: object) => submitPlanTool(h.state).handler(p, h.state);
  const propose = (args: Record<string, unknown>) => proposeRailTool(h.state).handler({
    taskId: 'task-1', targetScope: 'GLOBAL', proposedValue: '', reason: 'the rail is wrong for this task', workerId: 'architect-1', ...args,
  }, h.state) as Promise<{ proposalId: string; status: string }>;
  const diskRails = () => (JSON.parse(fs.readFileSync(path.join(h.moePath, 'project.json'), 'utf-8')) as { globalRails: typeof RAILS }).globalRails;
  const proposalFiles = () => fs.readdirSync(path.join(h.moePath, 'proposals'));

  it.each([
    ['(g1) REMOVE a forbiddenPatterns entry', 'REMOVE_RAIL', 'console.log', '', FORBIDDEN_PLAN, 'Forbidden pattern: console.log', { forbiddenPatterns: ['rm -rf'] }],
    ['(g2) MODIFY a forbiddenPatterns entry', 'MODIFY_RAIL', 'console.log', 'console.debug', FORBIDDEN_PLAN, 'Forbidden pattern: console.log', { forbiddenPatterns: ['rm -rf', 'console.debug'] }],
    ['(g3) REMOVE a requiredPatterns entry', 'REMOVE_RAIL', 'error handling', '', REQUIRED_PLAN, 'Required pattern missing: error handling', { requiredPatterns: ['test'] }],
    ['(g4) MODIFY a requiredPatterns entry', 'MODIFY_RAIL', 'error handling', 'constant', REQUIRED_PLAN, 'Required pattern missing: error handling', { requiredPatterns: ['constant', 'test'] }],
  ] as const)('%s: PENDING, approval edits exactly that entry on disk, and the refused plan is accepted', async (_title, proposalType, currentValue, proposedValue, refusedPlan, violation, changed) => {
    const { proposalId, status } = await propose({ proposalType, currentValue, proposedValue });
    expect(status).toBe('PENDING');
    await expect(submit(refusedPlan)).rejects.toThrow(violation);

    await h.state.approveProposal(proposalId);
    await h.state.load();
    const expected = { ...RAILS, ...changed };
    expect(h.state.project!.globalRails).toEqual(expected);
    expect(diskRails()).toEqual(expected);
    expect(h.state.proposals.get(proposalId)!.status).toBe('APPROVED');

    await submit(refusedPlan);
    expect(h.state.getTask('task-1')!.status).toBe('AWAITING_APPROVAL');
  });

  it('(g5) a GLOBAL value in no rail list is a coded NOT_FOUND refusal that writes nothing', async () => {
    const err = await propose({ proposalType: 'REMOVE_RAIL', currentValue: 'no such rail' }).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(MoeError);
    expect(err).toMatchObject({ codeName: 'NOT_FOUND' });
    expect((err as Error).message).toContain('Rail not found');
    expect(h.state.proposals.size).toBe(0);
    expect(proposalFiles()).toEqual([]);
  });

  it('(g6) a GLOBAL value in two rail lists is a coded INVALID_INPUT refusal that writes nothing', async () => {
    h.state.project!.globalRails.customRules = ['console.log'];
    const err = await propose({ proposalType: 'MODIFY_RAIL', currentValue: 'console.log', proposedValue: 'x' }).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(MoeError);
    expect(err).toMatchObject({ codeName: 'INVALID_INPUT' });
    expect((err as Error).message).toContain('Ambiguous rail match');
    expect(h.state.proposals.size).toBe(0);
    expect(proposalFiles()).toEqual([]);
  });

  it('(g7) approval re-resolves: a value gone since the proposal is a coded refusal that changes nothing', async () => {
    const { proposalId } = await propose({ proposalType: 'REMOVE_RAIL', currentValue: 'console.log' });
    h.state.project!.globalRails.forbiddenPatterns = ['rm -rf'];
    const before = fs.readFileSync(path.join(h.moePath, 'project.json'), 'utf-8');
    await expect(h.state.approveProposal(proposalId)).rejects.toMatchObject({ codeName: 'NOT_FOUND' });
    expect(fs.readFileSync(path.join(h.moePath, 'project.json'), 'utf-8')).toBe(before);
    expect(h.state.proposals.get(proposalId)!.status).toBe('PENDING');
  });

  it('(g8) GLOBAL ADD_RAIL still appends to customRules only', async () => {
    const { proposalId } = await propose({ proposalType: 'ADD_RAIL', proposedValue: 'console.log' });
    await h.state.approveProposal(proposalId);
    await h.state.load();
    expect(h.state.project!.globalRails).toEqual({ ...RAILS, customRules: ['Keep it simple', 'console.log'] });
  });
});
```
DoD map: (g1) to (g4) are DoD 1, each with a reload from disk and the refused plan accepted afterwards. (g5) and (g6) are DoD 2. (g7) proves that approval re-resolves the value. (g8) is the ADD_RAIL regression.

Rewrite packages/moe-daemon/src/state/railChange.ts with your Write tool, as below (dry-run tsc clean).
- findRailIndex keeps its signature and exact-then-trimEnd matching. Its two throws become coded, and the text stays 'Rail not found for proposal <id>' / 'Ambiguous rail match for proposal <id>'. StateManager.test.ts:936 and proposeRail.test.ts:127 match those substrings.
```ts
import type { GlobalRails, RailProposal } from '../types/schema.js';
import { MoeError, MoeErrorCode } from '../util/errors.js';

/** The GLOBAL lists a MODIFY_RAIL or REMOVE_RAIL can reach. ADD_RAIL only appends to customRules. */
export const GLOBAL_RAIL_LISTS = ['customRules', 'forbiddenPatterns', 'requiredPatterns'] as const;
export type GlobalRailList = typeof GLOBAL_RAIL_LISTS[number];

/** The exact entry if one exists, else every entry equal once trailing whitespace is trimmed. */
function railMatches(rails: readonly string[], value: string): number[] {
  const exact = rails.indexOf(value);
  if (exact !== -1) return [exact];
  return rails.flatMap((rail, index) => rail.trimEnd() === value.trimEnd() ? [index] : []);
}

const railNotFound = (proposalId: string) =>
  new MoeError(MoeErrorCode.NOT_FOUND, `Rail not found for proposal ${proposalId}`, { proposalId });
const ambiguousRail = (proposalId: string, lists: readonly string[] = []) =>
  new MoeError(MoeErrorCode.INVALID_INPUT,
    `Ambiguous rail match for proposal ${proposalId}${lists.length ? ` (${lists.join(', ')})` : ''}`, { proposalId, lists });

/** Resolve an approved rail's original text without losing insignificant trailing whitespace. */
export function findRailIndex(rails: string[], value: string, proposalId: string): number {
  const matches = railMatches(rails, value);
  if (matches.length === 0) throw railNotFound(proposalId);
  if (matches.length > 1) throw ambiguousRail(proposalId);
  return matches[0];
}

/** The one GLOBAL list holding a MODIFY/REMOVE value. None, or several, is a coded refusal. */
export function resolveGlobalRail(
  rails: GlobalRails | undefined, value: string, proposalId: string
): { list: GlobalRailList; index: number } {
  const hits = GLOBAL_RAIL_LISTS.flatMap((list) => {
    const matches = railMatches(rails?.[list] ?? [], value);
    if (matches.length > 1) throw ambiguousRail(proposalId, [list]);
    return matches.length === 1 ? [{ list, index: matches[0] }] : [];
  });
  if (hits.length === 0) throw railNotFound(proposalId);
  if (hits.length > 1) throw ambiguousRail(proposalId, hits.map((hit) => hit.list));
  return hits[0];
}

/** The globalRails an approved GLOBAL proposal produces. Pure: the caller persists it. */
export function applyGlobalRailChange(rails: GlobalRails, proposal: RailProposal): GlobalRails {
  const next: GlobalRails = { ...rails };
  if (proposal.proposalType === 'ADD_RAIL') {
    next.customRules = [...(rails.customRules ?? []), proposal.proposedValue];
    return next;
  }
  const { list, index } = resolveGlobalRail(rails, proposal.currentValue ?? '', proposal.id);
  const edited = [...rails[list]];
  if (proposal.proposalType === 'MODIFY_RAIL') edited[index] = proposal.proposedValue;
  else edited.splice(index, 1);
  next[list] = edited;
  return next;
}
```
Error handling: every refusal is a coded MoeError thrown before any write. railNotFound is NOT_FOUND. ambiguousRail is INVALID_INPUT and covers both two matches inside one list and hits in two lists. GlobalRails' three lists are required string[] in types/schema.ts, so `rails[list]` needs no fallback after resolution.

planningNotes.codebaseInsights:
checkPlanRails (util/rails.ts) enforces only globalRails.forbiddenPatterns and requiredPatterns, by case-insensitive substring. Epic and task rails are guidance only.
Nothing after init writes those two lists, which is why the escape hatch was dead.
The WS APPROVE_PROPOSAL handler (WebSocketServer.ts:815) lets an approval error reach its generic error reply, so a coded error only adds a prefix to the text.
ToolTestHarness.setupMoeFolder takes a globalRails override and creates file.ts, so an accepted plan with affectedFiles ['file.ts'] works. Its approvalMode is CONTROL, so an accepted plan goes to AWAITING_APPROVAL with no speed timers.
